# Traditional ACID transaction (monolith)
BEGIN TRANSACTION;
  UPDATE inventory SET stock = stock - 1 WHERE product_id = 1;
  INSERT INTO payments (amount, status) VALUES (149.99, 'completed');
  INSERT INTO shipments (order_id, status) VALUES (789, 'pending');
COMMIT;

# Distributed transaction (microservices)
# Service A: Inventory -> deduct stock (success)
# Service B: Payment -> charge customer (success)
# Service C: Shipping -> create shipment (FAILS!)
# Result: Money charged, stock deducted, no shipment
# This is the distributed transaction problem!
